  ('learn-coding', 'Coding Foundations', 'Learn the basics of coding and use small projects to build confidence before deeper learning.', array['Set up your workspace', 'Learn basic logic', 'Build a simple script', 'Practice with mini projects']::text[]),
  ('learn-ml', 'Machine Learning Foundations', 'Understand the big ideas behind ML, data patterns, and beginner-friendly experiments.', array['Learn key ML concepts', 'Work with data', 'Try a notebook', 'Practice and review']::text[]),
  ('design-cad', 'Design and CAD Path', 'Use design thinking and simple CAD tools to build creative ideas and prototypes with confidence.', array['Learn design basics', 'Explore a tool', 'Create simple concepts', 'Refine and share']::text[]),
  ('build-app', 'App Building Path', 'Start with simple app ideas, product thinking, and the tools that help you build a first version.', array['Define the idea', 'Sketch the user flow', 'Create a prototype', 'Test and improve']::text[]),
  ('no-code', 'No-Code Starter', 'Use easy tools to build workflows and small systems without needing to write code.', array['Choose a simple problem', 'Map the flow', 'Build the workflow', 'Review and improve']::text[]),
  ('ai-productivity', 'AI Productivity Path', 'Learn how AI can support writing, planning, research, and daily work in a practical way.', array['Identify daily repetitive tasks', 'Create reusable prompts', 'Apply AI to real work', 'Review and improve results']::text[])
